const e="artigras-youth-art-competition",u=2025,t="Built from the 2025 Rules & Regulations only. The text says artwork may be dropped at 'one of the three following locations' but prints only two (Palm Beach North Chamber of Commerce and Resource Depot). The pick-up text prints mixed dates (Sunday February 18; February 20 to March 7, 2024; March 8, 2024) that do not match the 2025 festival year; they are kept as printed in the Variable. No judging criteria, ages or entry fees are printed.",o={Title:"Rules & Criteria",Subtitle:"ArtiGras Youth Art Competition, grades K-12",NoticeTitle:"Please Read Before Registering",Notice:"Artwork is due by {{ArtworkDeadline}}. Theme: {{Theme}}.",Notes:["Each school may submit one piece of artwork from each grade level.","All artwork must incorporate the theme in some way."],Sections:[{Key:"general",Title:"General",Items:[{Text:"The Youth Art Competition is a juried art competition for grade levels K-12 that features award money to the winning students and schools.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"The theme is {{Theme}}. It focuses on the beauty and diversity of the natural world. Examples are landscapes and scenery, seasons, ecosystems, habitats, environmental awareness, and flora and fauna.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Students are encouraged to create artwork of what nature means to them and to experiment with new methods and materials.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"All artwork must incorporate the theme in some way.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"eligibility",Title:"Eligibility",Items:[{Text:"Schools in Palm Beach County may take part.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Each school may submit one piece of artwork from each grade level, from Kindergarten to Grade 12.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Artwork submitted by home schools is not accepted. The mission of the competition is to support school art programs in local Palm Beach County schools.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"A completed release form must be attached or pasted to the back of each entry.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"registration",Title:"How to enter",Items:[{Text:"Drop off the artwork at one of the designated drop-off locations by {{ArtworkDeadline}}. The deadline lets the organiser publish the participating schools in the media.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Drop-off places: {{DropOffChamber}} and {{DropOffResourceDepot}}.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Any 2-D medium may be used (for example watercolor, oil, ink, clay pencil, photography).",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Artwork size is a minimum of 8.5 x 11 inches and a maximum of 12 x 18 inches, not including the mat.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Do not laminate or frame the artwork. All artwork must be matted and wrapped for outdoor protection so it is preserved through the festival and set-up.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Pick-up: {{ArtworkPickup}}.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Artwork must be checked out by the student or the student's parent or guardian. Artwork is not released to the parents or guardians of other students unless previously approved. To approve someone else, contact the organiser by the printed date.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"judging",Title:"Judging",Items:[{Text:"All artwork submitted is judged by the Youth Art Jury. The decision of the Youth Art Jury is final.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"The judges choose five winners from each grade: 1st, 2nd and 3rd place and two honorable mentions.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"A Best of Show award goes to one Elementary, one Middle and one High School student.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"prizes",Title:"Awards and prizes",Items:[{Text:"Five awards are given in each grade level: 1st Place, 2nd Place, 3rd Place and two Honorable Mentions. All honorable mentions and award winners receive an ArtiGras Awards Ribbon.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"The Best of Show winner also receives a {{BestOfShowStudentPrize}} check in the student's name. Checks can only be awarded to students who win Best of Show or 1st place.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Schools with winning students receive prize money for their art programs: {{SchoolPrizes}}.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Winners are displayed in the Youth Art Competition area on both festival days.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Winners come to the Chamber to sign out their checks once the festival is over. Winners are notified when checks are ready.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Each student aged 12 or under who submits artwork receives two tickets to the festival, as do art teachers submitting artwork. Each student aged 13 or older receives three tickets. Children aged 12 and under attend the festival free, thanks to the sponsor.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"dates",Title:"Dates",Items:[{Text:"Festival and winners on display: {{FestivalDates}}.",Source:"2025 Youth Art Competition Rules & Regulations"},{Text:"Artwork due: {{ArtworkDeadline}}.",Source:"2025 Youth Art Competition Rules & Regulations"}]},{Key:"other",Title:"Publicity",Items:[{Text:"All entries and artist details (full name, school, city and state) may be used in publicity campaigns for this promotion and future promotions.",Source:"2025 Youth Art Competition Rules & Regulations"}]}],Documents:[{Title:"2025 Youth Art Competition Rules & Regulations",Url:"https://www.artigras.org/wp-content/uploads/2024/09/2025-Youth-Art-Competition-Rules-and-Regulations.pdf"}]},r=[],a=[],i=[{Title:"Youth Art (2-D Artwork)",Source:"2025 Youth Art Competition Rules & Regulations",Sections:{About:null,TimeAndFormat:["Minimum 8.5 x 11 inches, maximum 12 x 18 inches, not including the mat."],Rules:["One piece of artwork per school from each grade level.","Matted and wrapped for outdoor protection; release form attached to the back.","The artwork must incorporate the theme."],Allowed:["Any 2-D medium (watercolor, oil, ink, clay pencil, photography and similar)."],NotAllowed:["Laminated or framed artwork.","Home-school entries."],Judging:["Five winners per grade: 1st, 2nd, 3rd and two honorable mentions; Best of Show for one Elementary, one Middle and one High School student.","The decision of the Youth Art Jury is final."],Points:null,Notes:null},Markdown:`## Time and format
- Minimum 8.5 x 11 inches, maximum 12 x 18 inches, not including the mat.

## Rules
- One piece of artwork per school from each grade level.
- Matted and wrapped for outdoor protection; release form attached to the back.
- The artwork must incorporate the theme.

## Allowed
- Any 2-D medium (watercolor, oil, ink, clay pencil, photography and similar).

## Not allowed
- Laminated or framed artwork.
- Home-school entries.

## Judging
- Five winners per grade: 1st, 2nd, 3rd and two honorable mentions; Best of Show for one Elementary, one Middle and one High School student.
- The decision of the Youth Art Jury is final.`}],n=[],s=[{Key:"Theme",Kind:"text",Label:"Theme",Value:"Nature's Palette",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"ArtworkDeadline",Kind:"date",Label:"Artwork drop-off deadline",Value:"Friday, December 13, 2024, 3:00 p.m.",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"FestivalDates",Kind:"date",Label:"Festival dates (40th anniversary)",Value:"February 15 and 16, 2025",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"ArtworkPickup",Kind:"text",Label:"Artwork pick-up",Value:"after the awards ceremony in the ArtiKids Zone on Sunday, February 18 (as printed); artwork not picked up at the festival can be collected at the Palm Beach North Chamber of Commerce office Monday to Thursday 9:00 a.m. to 3:00 p.m. between February 20 and March 7; artwork not collected by Friday, March 8 at 3:00 p.m. is donated to local organizations at the Chamber's discretion; to let someone else collect, contact the organiser by Friday, February 7",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"BestOfShowStudentPrize",Kind:"prize",Label:"Best of Show student check",Value:"$100",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"SchoolPrizes",Kind:"prize",Label:"Prize money for winning students' schools",Value:"Best in Show students and their schools receive $100 each; 1st place winning students and their schools receive $90 each; 2nd place winners' school receives $75; 3rd place winners' school receives $50",Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"DropOffChamber",Kind:"address",Label:"Drop-off: Palm Beach North Chamber of Commerce",Value:{Name:"Palm Beach North Chamber of Commerce (Mon-Fri 9:00 a.m.-5:00 p.m.)",Address:"5520 PGA Boulevard, Suite 200",City:"Palm Beach Gardens, Florida 33418",MapUrl:"",Directions:"Take I-95 to the PGA Boulevard west exit. Head west 1.0 miles, pass PGA Commons, and turn left at the light onto Ave of the PGA. Make a left into the plaza and head east to the opposite side. The Chamber office is on your left above a restaurant. Phone (561) 746-7111."},Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"DropOffResourceDepot",Kind:"address",Label:"Drop-off: Resource Depot",Value:{Name:"Resource Depot (Tue-Thu 11:00 a.m.-4:45 p.m.; Sat 9:00 a.m.-1:45 p.m.)",Address:"2508 Florida Avenue",City:"West Palm Beach, FL 33401",MapUrl:"",Directions:"From I-95 exit at Belvedere and head east 7/10 of a mile to Florida Avenue, one block west of Dixie Hwy. Turn left on Florida Ave across from the Publix in Belmart Plaza. The entrance is off Florida Ave on the north side of the large gray building. Phone (561) 882-0090."},Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"OrganiserContact",Kind:"contact",Label:"Contact for questions",Value:{Name:"Caitlyn Bergman",Role:"Palm Beach North Chamber of Commerce, Youth Art Competition contact",Phone:"561-748-3945",WhatsApp:"",Email:"caitlyn@pbnchamber.com"},Source:"2025 Youth Art Competition Rules & Regulations"},{Key:"Announcements",Kind:"news",Label:"News printed in the rules",Value:[{Date:"",Title:"40th anniversary of ArtiGras",Text:"The 2025 festival celebrates the 40th anniversary of the ArtiGras Fine Arts Festival. The organiser notes that changes were made to the rules this year.",Url:"https://www.artigras.org/wp-content/uploads/2024/09/2025-Youth-Art-Competition-Rules-and-Regulations.pdf"}],Source:"2025 Youth Art Competition Rules & Regulations"}],l=[{Claim:"Registration content captured from the organiser's own 2025 rules.",SourceType:"Primary - the event's own rules document",Source:"2025 Youth Art Competition Rules & Regulations",Url:"https://www.artigras.org/wp-content/uploads/2024/09/2025-Youth-Art-Competition-Rules-and-Regulations.pdf"}],h={TemplateKey:e,Year:2025,Note:t,Page:o,ParticipantTypes:r,AgeGroups:a,Competitions:i,CompetitionAgeGroups:n,Variables:s,Evidence:l};export{a as AgeGroups,n as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,o as Page,r as ParticipantTypes,e as TemplateKey,s as Variables,u as Year,h as default};
